from playwright.sync_api import sync_playwright
S='/tmp/claude-0/-home-claude/abce22cd-6235-5141-b5ff-f91aa22653ed/scratchpad'
def ok(n,c,x=''): print(('PASS ' if c else 'FAIL ')+n+(' '+str(x) if x!='' else ''),flush=True)
with sync_playwright() as p:
    b=p.chromium.launch(executable_path='/usr/bin/google-chrome',args=['--use-angle=swiftshader','--enable-unsafe-swiftshader'])
    pg=b.new_page(viewport={'width':1280,'height':720}); ev=pg.evaluate; W=pg.wait_for_timeout; errs=[]
    pg.on('pageerror',lambda e:errs.append(str(e)))
    pg.goto('http://127.0.0.1:8766/'); W(900)
    ev("document.querySelector('#mainscreen')?.remove();RUNNING=true;state=freshState();normalizeState();state.introDone=true;state.storyFlags.noFeel=1;state.carSeen=Object.keys(CAR_INTRO);state.storyFlags.seedTalk=1;state.storyFlags.metDragon=1;state.storyFlags.noteTip=1;state.currentPhase='docked';state.currentLocation='starIslands';state.journeyCount=3;state.visitedLocations=['dawnForest','starIslands'];"
       "for(const id of ['sola','frost']){state.discoveredLifeforms.push(id);state.passengers[id]={stage:id==='sola'?2:1,talks:1,records:[],aboard:true,left:false,boardedJourney:2,zone:PASSENGERS[id].zone}};state.currentCarriage='habitat';render()"); W(500)
    ev("act('exit','')"); W(500)
    ok('E1 leaving the train: familiar passengers can come along', ev("!!document.querySelector('[data-comp=\"sola\"]')") and not ev("!!document.querySelector('[data-comp=\"frost\"]')"))
    pg.click('[data-comp="sola"]'); W(1300)
    ok('E2 outside with a companion', ev("state.currentPhase")=='outside' and ev("state.companion")=='sola' and ev("!!document.querySelector('[data-hs=\"out-comp-si\"]')"))
    n=ev("document.querySelectorAll('[data-hs^=\"out-f\"]').length"); ok('E3 forage spots: 3 + 1 found by the companion', n==4, n)
    pg.screenshot(path=S+'/out1.png')
    mats=ev("forageNow().spots.map(s=>s.m)")
    for i in range(4): ev(f"forageTake({i})"); W(150)
    ok('E4 foraging collects materials / seeds', sum(ev(f"matCount('{m}')") for m in ['sand','stardust','dew','mosslight'])+ev("seedTotal()")+(1 if ev("state.collectibles.includes('seed_tidebloom')") else 0)>=3 and ev("document.querySelectorAll('[data-hs^=\"out-f\"]').length")==0, mats)
    ok('E5 sola shows a place only she knows', ev("!!document.querySelector('[data-hs=\"out-drift\"]')"))
    ev("placeVisit('sola')"); W(400)
    ok('E6 special place: seed + memory crystal + journal', ev("MEMORIES.find(m=>m.id==='place_sola').have()") and ev("state.log.some(l=>/浮島漂走/.test(l.t))"))
    ev("closeAll();compTalk()"); W(400); t=pg.locator('.dlg .tx').last.inner_text(); pg.locator('.dlg .box').last.click(); W(300)
    ok('E7 companion has a line for this place', '我的星河' in t, t)
    ev("act('back','')"); W(1200); ok('E8 back on the train, companion returns', ev("state.currentPhase")=='docked' and ev("state.companion")==None)
    ev("state.journeyCount=4;state.currentLocation='starIslands'"); f=ev("forageNow().spots.map(s=>s.m)")
    ok('E9 next stop, new forage', all(m in ('sand','stardust','seed_tidebloom') or m.startswith('sd:') for m in f), f)
    # materials: watering + purifying
    ev("state.materials={dew:1,mosslight:1};gardenSync();state.pods[0]={p:'dewmoss',st:1,j:4};state.currentCarriage='nature';render();gardenPanel(0)"); W(400)
    pg.click('[data-mat="dew"]'); W(800)
    ok('E10 dew waters the pod → blooms now', ev("state.pods[0].st")==2 and ev("matCount('dew')")==0)
    ev("closeAll();state.spirit.taint=30;INTERACT['nat:special']()"); W(400); ev("document.querySelector('#vm')?.click()"); W(250); pg.click('[data-mat="mosslight"]'); W(300)
    ok('E11 moss light at the vine purifies −8', ev("state.spirit.taint")==22)
    ev("closeAll();seedPanel()"); W(300); ok('E12 seed vault lists materials', '採集材料' in pg.inner_text('#layer')); ev("closeAll()")
    # unlocks
    ev("starMap()"); W(400); pg.click('[data-st="reverseRealm"]'); W(200); info=pg.inner_text('#smi')
    ok('E13 locked realm shows what is needed', '守護者線索' in info and '古列車座' in info, info)
    ev("closeAll();state.clues=['clue_wake','clue_ring','clue_voyage','clue_seed'];state.consts=['train'];render()"); W(1300)
    ok('E14 conditions met → coordinates revealed', ev("revealed('reverseRealm')") and ev("state.log.some(l=>/解讀出新的座標/.test(l.t))"))
    ev("starMap()"); W(400); pg.click('[data-st="reverseRealm"]'); W(200); info=pg.inner_text('#smi')
    ok('E15 star map shows the realm, route not open yet', '逆生之境' in info and '航道還沒有開通' in info, info)
    pg.screenshot(path=S+'/unlock.png')
    ok('E16 no errors', not errs, errs)
    b.close()
